#include <iostream>
#include <string>
void inspect(const std::string&){ std::cout<<"lvalue-compatible\n"; }
void inspect(std::string&&){ std::cout<<"rvalue\n"; }
int main(){ std::string s="named"; inspect(s); inspect(std::string{"temp"}); }

#include <iostream>
#include <utility>
#include <vector>
int main(){ std::vector<int> a(100000,7); auto before=a.data(); std::vector<int> b=std::move(a); std::cout<<std::boolalpha<<(b.data()==before)<<' '<<b.size()<<'\n'; }

